import{_ as d,l as n,o as r,c as o,v as s,p as E,x as l,d as t,i as m,S as p,b as e}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"杠杆与波动拖累","description":"","frontmatter":{"title":"杠杆与波动拖累","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/leverage-volatility-drag.md","filePath":"quant/leverage-volatility-drag.md","lastUpdated":1789023840000}'),h={name:"quant/leverage-volatility-drag.md"};function B(b,a,u,g,A,f){const i=n("Mermaid");return r(),o("div",null,[a[1]||(a[1]=s('<h1 id="杠杆与波动拖累" tabindex="-1">杠杆与波动拖累 <a class="header-anchor" href="#杠杆与波动拖累" aria-label="Permalink to &quot;杠杆与波动拖累&quot;">​</a></h1><div class="epigraph"><p>每日再平衡的杠杆 ETF 的复利，不等于标的复利乘杠杆倍数；方差项把路径拉向几何均值。</p><footer>—— 对照 Cheng and Madhavan 对杠杆 ETF 路径依赖的分析；波动拖累见连续时间财富 $r-\\tfrac12\\sigma^2$ 项</footer></div><p><a href="/quant/target-date-glidepath">上一课</a>的路径默认未杠杆化。本课缺口是 <strong>\\(2\\times\\)、\\(3\\times\\) 与融资杠杆的离散再平衡</strong>：算术收益可以是 \\(\\lambda\\) 倍，几何收益少一块 \\(\\tfrac12\\lambda(\\lambda-1)\\sigma^2\\) 量级的拖累。主干 Kelly 已有杠杆上限；这里写清楚拖累与再平衡溢价的符号关系，后课专门写再平衡溢价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设标的日收益 \\(r_t\\)，杠杆 ETF 近 \\(\\lambda r_t\\) 再扣费。多日财富 \\(\\prod(1+\\lambda r_t)\\)，不是 \\((1+\\lambda\\bar r)^T\\)。对数近似 \\(\\lambda\\mu-\\tfrac12\\lambda^2\\sigma^2\\) 对对数效用投资者，而标的是 \\(\\mu-\\tfrac12\\sigma^2\\)。杠杆既放大漂移也放大方差项。震荡市里标的来回、杠杆产品因每日重置而锁亏——这是凸性/再平衡，不是「产品骗人」。问题是把拖累写成预期项，放进 Merton 实现，而不是在回测里用算术 \\(\\lambda\\bar r\\) 当持有期收益。</p><p>融资杠杆（借钱买股票、不每日精确重置）的拖累形式不同：利息是现金，再平衡不是强制每日。不要把杠杆 ETF 的路径公式套到经纪商保证金账户上。</p><h3 id="拖累不是费用的别名" tabindex="-1">拖累不是费用的别名 <a class="header-anchor" href="#拖累不是费用的别名" aria-label="Permalink to &quot;拖累不是费用的别名&quot;">​</a></h3><p>管理费与融资利率是另一项。波动拖累在零费用下仍在。高 \\(\\sigma\\)、高 \\(\\lambda\\)、长持有、震荡（负自相关）时拖累大；趋势市（正自相关）里每日再平衡可以获利，即后课再平衡溢价的反面或同面，取决于你站在产品哪一侧。</p><p><span class="marginnote">波动瞄准策略每日调杠杆，也有同类路径项。把它当免费的「稳夏普」，忽略了调仓冲击与拖累。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告持有期收益用产品 NAV 路径，不用 \\(\\lambda\\times\\) 指数收益。预测：用预期 \\(\\sigma\\)（HAR）估拖累，持有期超过数日的杠杆 ETF 必须有这项。对冲：用期货加现金复制杠杆暴露，控制再平衡频率，使拖累成为选择而不是产品强制。Merton：\\(\\lambda\\) 进 \\(\\pi\\)，但效用按几何，自动惩罚过高 \\(\\lambda\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每日重置把暴露钉在 \\(\\lambda\\)，等价于持续买卖：涨则加仓、跌则减仓（对多头杠杆）。震荡时买高卖低。这与固定份额组合的再平衡相反或相同，取决于比较对象。连续时间 Itô 的 \\(-\\tfrac12\\sigma^2\\) 是同一数学。</p>',13)),(r(),E(p,null,{default:l(()=>[m(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Daily%5B%22%E6%AF%8F%E6%97%A5%E9%87%8D%E7%BD%AE%E6%9A%B4%E9%9C%B2%E5%88%B0%20%CE%BB%22%5D%20--%3E%20Path%5B%22%E2%88%8F%201%20%E5%8A%A0%20%CE%BB%20r%22%5D%0A%20%20Path%20--%3E%20Drag%5B%22%E5%87%A0%E4%BD%95%E5%B0%8F%E4%BA%8E%20%CE%BB%20%E5%80%8D%E7%AE%97%E6%9C%AF%22%5D%0A%20%20Vol%5B%22%CF%83%20%E4%B8%8E%20%CE%BB%22%5D%20--%3E%20Drag%0A%20%20Trend%5B%22%E8%B6%8B%E5%8A%BF%E5%AF%B9%E9%9C%87%E8%8D%A1%22%5D%20--%3E%20Sign%5B%22%E6%8B%96%E7%B4%AF%E6%88%96%E5%86%8D%E5%B9%B3%E8%A1%A1%E5%A2%9E%E7%9B%8A%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"隔夜跳、跟踪误差、对手方（ETN）不是拖累公式能覆盖的。反向杠杆在趋势下跌中可赢，但仍有方差项。本课不建议用杠杆 ETF 当长期 TDF 核心。监管与适当性另论。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"每日杠杆的复利不是 \\(\\lambda\\) 倍标的复利；方差项是一等公民。"),e("li",null,"融资杠杆与杠杆 ETF 的重置规则不同，公式不可混用。"),e("li",null,"震荡锁亏、趋势可能增益，接到再平衡溢价。"),e("li",null,"出处：Cheng and Madhavan 对杠杆 ETF 的分析；Itô 公式的几何均值项。")],-1))])}const D=d(h,[["render",B]]);export{T as __pageData,D as default};
